DO $$
DECLARE uid bigint;actor bigint;missing_uid bigint;preview jsonb;r jsonb;r2 jsonb;body jsonb;day_key date;cards integer;bal numeric;topics text[]:=ARRAY['intro','protocol','models','billing','security','troubleshoot'];topic text;key text;streak_no integer;cfg jsonb;
BEGIN
 INSERT INTO users(email,password_hash,role,balance,created_at) VALUES('card-admin-'||gen_random_uuid()::text||'@example.com','fixture','admin',0,now()-interval '40 days') RETURNING id INTO actor;
 INSERT INTO users(email,password_hash,balance,created_at) VALUES('card-qa-'||gen_random_uuid()::text||'@example.com','fixture',0,now()-interval '40 days') RETURNING id INTO uid;
 INSERT INTO users(email,password_hash,balance,created_at) VALUES('card-empty-'||gen_random_uuid()::text||'@example.com','fixture',0,now()-interval '40 days') RETURNING id INTO missing_uid;
 UPDATE vip_rules SET payload=jsonb_set(payload,'{enabled}','true');
 INSERT INTO achievement_vip_history(effective_at,rules) VALUES(now()-interval '41 days','{"enabled":true,"tiers":[{"level":1,"threshold":100},{"level":2,"threshold":300}]}');
 INSERT INTO achievement_daily_history(effective_at,rewards) VALUES(now()-interval '41 days','[0.01,0.05,0.10,0.25,0.50,1.00]');
 INSERT INTO vip_recharge_ledger(user_id,source,source_id,amount,created_at) VALUES(uid,'admin_balance',gen_random_uuid()::text,100,now()-interval '40 days'),(uid,'admin_balance',gen_random_uuid()::text,200,now());
 UPDATE achievement_config SET payload=payload||'{"cash_enabled":true,"cash_scope":"all","budget_enabled":false,"milestone_cash_enabled":false}'::jsonb;
 FOREACH topic IN ARRAY topics LOOP INSERT INTO achievement_activity_passes(user_id,kind,topic) VALUES(uid,'knowledge',topic);END LOOP;
 FOREACH key IN ARRAY ARRAY['A-K01','A-K02','A-K03'] LOOP r:=achievement_claim(uid,key);END LOOP;
 IF achievement_card_balance(uid)<>6 OR (SELECT balance FROM users WHERE id=uid)<>0 THEN RAISE EXCEPTION 'Card awards changed cash or wrong count'; END IF;
 r:=achievement_claim(uid,'A-K03');IF NOT (r->>'replayed')::boolean OR achievement_card_balance(uid)<>6 THEN RAISE EXCEPTION 'Card replay duplicated award';END IF;
 BEGIN PERFORM achievement_claim(missing_uid,'A-K02'); RAISE EXCEPTION 'locked card accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_LOCKED' THEN RAISE;END IF;END;
 BEGIN PERFORM achievement_claim_series(uid,'A-K'); RAISE EXCEPTION 'cash-off series accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_CASH_UNAVAILABLE' THEN RAISE;END IF;END;
 day_key:=(date_trunc('month',now() AT TIME ZONE 'Asia/Shanghai'))::date-1;
 IF day_key<(now() AT TIME ZONE 'Asia/Shanghai')::date-30 THEN day_key:=(now() AT TIME ZONE 'Asia/Shanghai')::date-30;END IF;
 preview:=achievement_card_preview(uid,day_key);
 IF NOT (preview->>'available')::boolean OR (preview->>'tier')::integer<>1 OR (preview->>'gross')::numeric<>.05 THEN RAISE EXCEPTION 'Cross-month historical preview %',preview;END IF;
 body:=jsonb_build_object('date',day_key,'request_key',gen_random_uuid(),'expected_gross',.05,'expected_tier',1);
 BEGIN PERFORM achievement_use_card(uid,jsonb_set(body,'{date}',to_jsonb(((now() AT TIME ZONE 'Asia/Shanghai')::date)::text)));RAISE EXCEPTION 'today accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_CARD_DATE_INVALID' THEN RAISE;END IF;END;
 BEGIN PERFORM achievement_use_card(uid,jsonb_set(body,'{date}',to_jsonb(((now() AT TIME ZONE 'Asia/Shanghai')::date-31)::text)));RAISE EXCEPTION 'old date accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_CARD_DATE_INVALID' THEN RAISE;END IF;END;
 BEGIN PERFORM achievement_use_card(uid,jsonb_set(body,'{expected_gross}','0.10'));RAISE EXCEPTION 'changed preview accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_HISTORY_CHANGED' THEN RAISE;END IF;END;
 UPDATE achievement_config SET payload=payload||'{"budget_enabled":true,"daily_budget":0,"monthly_budget":0}'::jsonb;
 BEGIN PERFORM achievement_use_card(uid,body);RAISE EXCEPTION 'budget bypass';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_BUDGET_EXHAUSTED' THEN RAISE;END IF;END;
 IF achievement_card_balance(uid)<>6 OR (SELECT balance FROM users WHERE id=uid)<>0 THEN RAISE EXCEPTION 'Failure consumed card or cash';END IF;
 UPDATE achievement_config SET payload=jsonb_set(payload,'{budget_enabled}','false');
 INSERT INTO vip_reward_debt(user_id,amount) VALUES(uid,.02);
 INSERT INTO achievement_checkins(user_id,day,request_key,tier,revision,reason,streak) VALUES(uid,day_key-1,'chain-before',1,1,'cash_disabled',1),(uid,day_key+1,'chain-after',1,1,'cash_disabled',1);
 r:=achievement_use_card(uid,body);
 IF (r->>'gross')::numeric<>.05 OR (r->>'net')::numeric<>.03 OR (r->>'offset_amount')::numeric<>.02 OR achievement_card_balance(uid)<>5 THEN RAISE EXCEPTION 'Bad historical credit %',r;END IF;
 SELECT streak INTO streak_no FROM achievement_checkins WHERE user_id=uid AND day=day_key+1;IF streak_no<>3 THEN RAISE EXCEPTION 'Streak not rebuilt';END IF;
 r2:=achievement_use_card(uid,body);IF NOT (r2->>'replayed')::boolean OR achievement_card_balance(uid)<>5 THEN RAISE EXCEPTION 'Card replay consumed again';END IF;
 BEGIN PERFORM achievement_use_card(uid,jsonb_set(body,'{date}',to_jsonb((day_key-2)::text)));RAISE EXCEPTION 'request reuse accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_CARD_CONFLICT' THEN RAISE;END IF;END;
 body:=jsonb_set(body,'{request_key}',to_jsonb(gen_random_uuid()::text));r:=achievement_use_card(uid,body);IF NOT (r->>'existing')::boolean OR (r->>'cards_spent')::integer<>0 THEN RAISE EXCEPTION 'Existing date consumed';END IF;
 UPDATE achievement_config SET payload=jsonb_set(payload,'{milestone_cash_enabled}','true');
 INSERT INTO achievement_claims(user_id,key,gross,net,offset_amount,revision) VALUES(uid,'A-K01',.1,.1,0,1);
 r:=achievement_claim_series(uid,'A-K');IF (r->>'gross')::numeric<>1.3 OR (r->>'prior_amount')::numeric<>.1 THEN RAISE EXCEPTION 'Series duplicated old amount %',r;END IF;
 r2:=achievement_claim_series(uid,'A-K');IF NOT (r2->>'replayed')::boolean THEN RAISE EXCEPTION 'series replay';END IF;
 BEGIN PERFORM achievement_claim_series(uid,'A-C');RAISE EXCEPTION 'future series accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_LOCKED' THEN RAISE;END IF;END;
 body:=jsonb_build_object('key','A-X01','reason','QA cards','request_key',gen_random_uuid(),'grant_reward',true,'reclaim_reward',false);
 r:=achievement_admin_operation(actor,uid,'grant',body);IF (r->>'cards_awarded')::integer<>1 THEN RAISE EXCEPTION 'Admin card grant';END IF;
 r2:=achievement_admin_operation(actor,uid,'grant',body);IF NOT (r2->>'replayed')::boolean THEN RAISE EXCEPTION 'admin replay';END IF;
 BEGIN PERFORM achievement_admin_operation(actor,uid,'grant',jsonb_set(body,'{grant_reward}','false'));RAISE EXCEPTION 'admin flag collision';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ACHIEVEMENT_ADMIN_CONFLICT' THEN RAISE;END IF;END;
 body:=jsonb_build_object('key','A-X01','reason','QA revoke','request_key',gen_random_uuid(),'grant_reward',false,'reclaim_reward',true);
 r:=achievement_admin_operation(actor,uid,'revoke',body);IF (r->>'cards_reclaimed')::integer<>1 THEN RAISE EXCEPTION 'Admin card reclaim';END IF;
 body:=jsonb_build_object('key','A-X01','reason','QA regrant','request_key',gen_random_uuid(),'grant_reward',true,'reclaim_reward',false);
 r:=achievement_admin_operation(actor,uid,'grant',body);IF achievement_card_balance(uid)<>5 THEN RAISE EXCEPTION 'Regrant duplicated cards';END IF;
 body:=jsonb_build_object('date',(now() AT TIME ZONE 'Asia/Shanghai')::date-30,'request_key',gen_random_uuid(),'expected_gross',.05,'expected_tier',1);
 PERFORM achievement_use_card(uid,body);
 UPDATE users SET balance=.02 WHERE id=uid;
 body:=jsonb_build_object('key','A-K01','reason','QA reclaim series','request_key',gen_random_uuid(),'grant_reward',false,'reclaim_reward',true);
 r:=achievement_admin_operation(actor,uid,'revoke',body);
 IF (r->>'cards_reclaimed')::int<>0 OR (r->>'series_debt_added')::numeric<>1.3 OR (SELECT amount FROM vip_reward_debt WHERE user_id=uid)<>1.38 THEN RAISE EXCEPTION 'Used card or series debt reclaim %',r; END IF;
 IF NOT EXISTS(SELECT 1 FROM achievement_checkins WHERE user_id=uid AND day=day_key AND source='card') THEN RAISE EXCEPTION 'Used card checkin erased';END IF;
 body:=jsonb_build_object('key','A-K01','reason','QA restore','request_key',gen_random_uuid(),'grant_reward',false,'reclaim_reward',false);
 PERFORM achievement_admin_operation(actor,uid,'restore',body);
 r:=achievement_claim_series(uid,'A-K');IF NOT (r->>'replayed')::boolean OR r->>'revoked_at' IS NULL THEN RAISE EXCEPTION 'Restore duplicated series';END IF;
 PERFORM set_config('cards.qa.uid',uid::text,true);
 RAISE NOTICE 'PASS: cards, cash-off, series completion, prior cash, history tier, cross-month, debt, failures, streak, replays, admin grant/reclaim';
END $$;
